document.addEventListener("DOMContentLoaded",function(){var e=document.getElementById("contact-form");if(e){var t=document.querySelector(".form-messege");e.addEventListener("submit",function(n){n.preventDefault(),fetch(e.getAttribute("action"),{method:"POST",body:new FormData(e),headers:{Accept:"application/json"}}).then(function(n){if(!n.ok)return n.json().then(function(e){throw new Error(e&&e.errors&&e.errors.map(function(e){return e.message}).join(", ")||"Oops! An error occurred and your message could not be sent.")});t&&(t.classList.remove("error"),t.classList.add("success"),t.textContent="Thanks for reaching out — we'll be in touch soon."),e.reset()}).catch(function(e){t&&(t.classList.remove("success"),t.classList.add("error"),t.textContent=e.message||"Oops! An error occurred and your message could not be sent.")})})}});